//! Bounded grammar induction over three-input Boolean worlds.
//!
//! The hypothesis set is generated by a fixed grammar, not supplied as candidate labels.
//! Evaluator target signatures are read separately and are never passed to choose_action.
//! Results are synthetic research artifacts, not physical discovery claims.
use std::{
    collections::{BTreeMap, BTreeSet},
    env, fs,
    process::Command,
};

const DOMAIN: usize = 8;
const MASK: u8 = 0xff;
const RANDOM_REPETITIONS: usize = 32;
const SHA256_K: [u32; 64] = [
    0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5,
    0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3, 0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174,
    0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc, 0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da,
    0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7, 0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967,
    0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13, 0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85,
    0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070,
    0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3,
    0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208, 0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2,
];

#[derive(Clone, Debug)]
struct Expr {
    text: String,
    sig: u8,
    depth: usize,
    mdl_bits: f64,
}
#[derive(Clone, Debug)]
struct Candidate {
    sig: u8,
    representative: String,
    expression_aliases: usize,
    mdl_bits: f64,
}
#[derive(Clone, Debug)]
struct Problem {
    id: String,
    split: String,
    initial: Vec<(u8, u8)>,
    budget: usize,
    costs: [u32; DOMAIN],
}
#[derive(Clone, Debug)]
struct Task {
    problem: Problem,
    target_sig: u8,
}
#[derive(Clone, Copy, Debug)]
enum Policy {
    Active,
    Fixed,
    Random,
    UniformEig,
    MdlEig,
}
impl Policy {
    fn name(self) -> &'static str {
        match self {
            Self::Active => "active_maximum_disagreement",
            Self::Fixed => "fixed_ascending_action",
            Self::Random => "seeded_random_action",
            Self::UniformEig => "uniform_expected_information_gain_per_cost",
            Self::MdlEig => "mdl_expected_information_gain_per_cost",
        }
    }
}
#[derive(Clone, Debug)]
struct Episode {
    split: String,
    policy: String,
    actions: Vec<u8>,
    remaining: Vec<u8>,
    status: String,
    target_in_grammar: bool,
    target_retained: Option<bool>,
    audit_action: Option<u8>,
    audit_mismatch: bool,
    total_cost: u32,
}
#[derive(Clone, Debug)]
struct Case {
    id: String,
    split: String,
    candidate_count: usize,
    initial_viable: usize,
    active: Episode,
    uniform_eig: Episode,
    mdl_eig: Episode,
    fixed: Episode,
    random: Vec<Episode>,
}

fn valid_id(s: &str) -> bool {
    !s.is_empty()
        && s.bytes()
            .all(|b| b.is_ascii_alphanumeric() || b == b'_' || b == b'-')
}
fn parse_signature(s: &str) -> Result<u8, String> {
    if s.len() != DOMAIN || !s.bytes().all(|b| b == b'0' || b == b'1') {
        return Err(format!(
            "signature must contain exactly {DOMAIN} binary outputs: {s:?}"
        ));
    }
    let mut sig = 0u8;
    for (action, byte) in s.bytes().enumerate() {
        if byte == b'1' {
            sig |= 1u8 << action;
        }
    }
    Ok(sig)
}
fn signature_string(sig: u8) -> String {
    (0..DOMAIN)
        .map(|a| if sig & (1u8 << a) != 0 { '1' } else { '0' })
        .collect()
}
fn variable_signature(variable: usize) -> u8 {
    let mut sig = 0u8;
    for action in 0..DOMAIN {
        let input = match variable {
            0 => (action >> 2) & 1,
            1 => (action >> 1) & 1,
            _ => action & 1,
        };
        if input == 1 {
            sig |= 1u8 << action;
        }
    }
    sig
}

/// Enumerate all syntax trees up to the bounded depth and group by complete truth table.
/// Commutative children are text-ordered to avoid counting swapped operands twice.
fn enumerate_grammar(max_depth: usize) -> Result<Vec<Candidate>, String> {
    if max_depth > 2 {
        return Err("v1 grammar depth is capped at 2 to bound expression enumeration".into());
    }
    let terminals = [
        ("0".to_owned(), 0u8),
        ("1".to_owned(), MASK),
        ("x".to_owned(), variable_signature(0)),
        ("y".to_owned(), variable_signature(1)),
        ("z".to_owned(), variable_signature(2)),
    ];
    let mut expressions: BTreeMap<String, Expr> = terminals
        .into_iter()
        .map(|(text, sig)| {
            let expr = Expr {
                text: text.clone(),
                sig,
                depth: 0,
                // PCFG prior: P(terminal)=1/2, then choose uniformly among five terminals.
                mdl_bits: 10.0f64.log2(),
            };
            (text, expr)
        })
        .collect();

    for depth in 1..=max_depth {
        let snapshot: Vec<Expr> = expressions.values().cloned().collect();
        let mut pending: BTreeMap<String, Expr> = BTreeMap::new();
        for a in &snapshot {
            let d = a.depth + 1;
            if d <= depth {
                let text = format!("NOT({})", a.text);
                pending.entry(text.clone()).or_insert(Expr {
                    text,
                    sig: (!a.sig) & MASK,
                    depth: d,
                    mdl_bits: 3.0 + a.mdl_bits,
                });
            }
        }
        for i in 0..snapshot.len() {
            for j in i..snapshot.len() {
                let a = &snapshot[i];
                let b = &snapshot[j];
                let d = a.depth.max(b.depth) + 1;
                if d > depth {
                    continue;
                }
                for (op, sig) in [
                    ("AND", a.sig & b.sig),
                    ("OR", a.sig | b.sig),
                    ("XOR", a.sig ^ b.sig),
                ] {
                    let text = format!("({} {} {})", a.text, op, b.text);
                    pending.entry(text.clone()).or_insert(Expr {
                        text,
                        sig,
                        depth: d,
                        mdl_bits: 3.0 + a.mdl_bits + b.mdl_bits,
                    });
                }
            }
        }
        for (text, expr) in pending {
            expressions.entry(text).or_insert(expr);
        }
    }

    let mut groups: BTreeMap<u8, Vec<Expr>> = BTreeMap::new();
    for expr in expressions.values() {
        groups.entry(expr.sig).or_default().push(expr.clone());
    }
    Ok(groups
        .into_iter()
        .map(|(sig, mut aliases)| {
            // A semantic function gets one prior, based on its shortest grammar derivation.
            aliases.sort_by(|a, b| {
                a.mdl_bits
                    .total_cmp(&b.mdl_bits)
                    .then_with(|| a.text.len().cmp(&b.text.len()))
                    .then_with(|| a.text.cmp(&b.text))
            });
            Candidate {
                sig,
                representative: aliases[0].text.clone(),
                expression_aliases: aliases.len(),
                mdl_bits: aliases[0].mdl_bits,
            }
        })
        .collect())
}

fn parse_initial(raw: &str) -> Result<Vec<(u8, u8)>, String> {
    if raw == "none" {
        return Ok(Vec::new());
    }
    let mut result = Vec::new();
    let mut seen = BTreeSet::new();
    for entry in raw.split(',') {
        let (a_raw, y_raw) = entry
            .split_once(':')
            .ok_or_else(|| format!("invalid observation {entry:?}"))?;
        let a: u8 = a_raw
            .parse()
            .map_err(|_| "invalid action in initial observation")?;
        let y: u8 = y_raw
            .parse()
            .map_err(|_| "invalid output in initial observation")?;
        if a as usize >= DOMAIN || y > 1 || !seen.insert(a) {
            return Err(format!(
                "out-of-range or duplicate initial observation {entry:?}"
            ));
        }
        result.push((a, y));
    }
    result.sort_unstable_by_key(|entry| entry.0);
    Ok(result)
}
fn parse_costs(raw: &str) -> Result<[u32; DOMAIN], String> {
    let values: Vec<u32> = raw
        .split(',')
        .map(|part| part.parse::<u32>().map_err(|_| format!("invalid action cost {part:?}")))
        .collect::<Result<_, _>>()?;
    if values.len() != DOMAIN || values.iter().any(|cost| *cost == 0 || *cost > 10_000) {
        return Err(format!("expected {DOMAIN} positive action costs no greater than 10000"));
    }
    let mut costs = [0u32; DOMAIN];
    costs.copy_from_slice(&values);
    Ok(costs)
}
fn parse_problems(raw: &str) -> Result<Vec<Problem>, String> {
    let mut result = Vec::new();
    let mut ids = BTreeSet::new();
    for (line_no, raw_line) in raw.lines().enumerate() {
        let line = raw_line.trim();
        if line.is_empty() || line.starts_with('#') {
            continue;
        }
        let f: Vec<_> = line.split('|').collect();
        if f.len() != 5 {
            return Err(format!("line {}: expected 5 fields", line_no + 1));
        }
        if !valid_id(f[0]) || !ids.insert(f[0].to_owned()) {
            return Err(format!("line {}: invalid or duplicate task ID", line_no + 1));
        }
        if !matches!(f[1], "train" | "validation" | "heldout") {
            return Err(format!("line {}: invalid split", line_no + 1));
        }
        let initial = parse_initial(f[2]).map_err(|e| format!("line {}: {e}", line_no + 1))?;
        let budget: usize = f[3].parse().map_err(|_| format!("line {}: invalid query budget", line_no + 1))?;
        if budget > DOMAIN {
            return Err(format!("line {}: budget cannot exceed {DOMAIN}", line_no + 1));
        }
        let costs = parse_costs(f[4]).map_err(|e| format!("line {}: {e}", line_no + 1))?;
        result.push(Problem {
            id: f[0].to_owned(),
            split: f[1].to_owned(),
            initial,
            budget,
            costs,
        });
    }
    for split in ["train", "validation", "heldout"] {
        if !result.iter().any(|p| p.split == split) {
            return Err(format!("missing required split {split}"));
        }
    }
    Ok(result)
}
fn parse_truth(raw: &str) -> Result<BTreeMap<String, u8>, String> {
    let mut result = BTreeMap::new();
    for (line_no, raw_line) in raw.lines().enumerate() {
        let line = raw_line.trim();
        if line.is_empty() || line.starts_with('#') {
            continue;
        }
        let f: Vec<_> = line.split('|').collect();
        if f.len() != 2 || !valid_id(f[0]) {
            return Err(format!(
                "line {}: malformed evaluator truth row",
                line_no + 1
            ));
        }
        let sig = parse_signature(f[1]).map_err(|e| format!("line {}: {e}", line_no + 1))?;
        if result.insert(f[0].to_owned(), sig).is_some() {
            return Err(format!(
                "line {}: duplicate evaluator truth ID",
                line_no + 1
            ));
        }
    }
    if result.is_empty() {
        return Err("evaluator truth fixture is empty".into());
    }
    Ok(result)
}
fn assemble(problems: Vec<Problem>, truth: BTreeMap<String, u8>) -> Result<Vec<Task>, String> {
    let pids: BTreeSet<_> = problems.iter().map(|p| p.id.clone()).collect();
    let tids: BTreeSet<_> = truth.keys().cloned().collect();
    if pids != tids {
        return Err("problem IDs and evaluator truth IDs differ".into());
    }
    let mut tasks = Vec::with_capacity(problems.len());
    for problem in problems {
        let target_sig = *truth.get(&problem.id).ok_or("missing evaluator truth")?;
        for (a, y) in &problem.initial {
            if (target_sig >> *a) & 1 != *y {
                return Err(format!(
                    "initial observation contradicts evaluator target for {}",
                    problem.id
                ));
            }
        }
        tasks.push(Task {
            problem,
            target_sig,
        });
    }
    Ok(tasks)
}
fn viable(candidates: &[Candidate], obs: &[(u8, u8)]) -> Vec<u8> {
    candidates
        .iter()
        .filter(|c| obs.iter().all(|(a, y)| ((c.sig >> a) & 1) == *y))
        .map(|c| c.sig)
        .collect()
}
fn next_rng(state: &mut u64) -> u64 {
    if *state == 0 {
        *state = 0x9e3779b97f4a7c15;
    }
    let mut x = *state;
    x ^= x << 13;
    x ^= x >> 7;
    x ^= x << 17;
    *state = x;
    x
}
fn stable_seed(s: &str) -> u64 {
    let mut h = 0xcbf29ce484222325u64;
    for b in s.bytes() {
        h ^= u64::from(b);
        h = h.wrapping_mul(0x100000001b3);
    }
    h
}

/// This policy sees only the surviving semantic hypotheses and available experiments.
fn posterior_weights(survivors: &[u8], candidates: &[Candidate]) -> Vec<(u8, f64)> {
    let mut weighted: Vec<(u8, f64)> = survivors
        .iter()
        .filter_map(|sig| {
            candidates
                .iter()
                .find(|candidate| candidate.sig == *sig)
                .map(|candidate| (*sig, 2.0f64.powf(-candidate.mdl_bits)))
        })
        .collect();
    let normalizer: f64 = weighted.iter().map(|(_, weight)| *weight).sum();
    if normalizer > 0.0 {
        for (_, weight) in &mut weighted {
            *weight /= normalizer;
        }
    }
    weighted
}
fn binary_entropy_bits(p_one: f64) -> f64 {
    let p = p_one.clamp(0.0, 1.0);
    let term = |x: f64| if x <= 0.0 { 0.0 } else { -x * x.log2() };
    term(p) + term(1.0 - p)
}
fn expected_information_gain_per_cost(
    action: u8,
    posterior: &[(u8, f64)],
    costs: &[u32; DOMAIN],
) -> f64 {
    let p_one: f64 = posterior
        .iter()
        .filter(|(sig, _)| (sig >> action) & 1 == 1)
        .map(|(_, weight)| *weight)
        .sum();
    binary_entropy_bits(p_one) / f64::from(costs[action as usize])
}
fn choose_uniform_eig_action(
    survivors: &[u8],
    available: &[u8],
    costs: &[u32; DOMAIN],
) -> Option<u8> {
    if survivors.is_empty() {
        return available.first().copied();
    }
    let mut best = None;
    let mut best_score = -1.0f64;
    for action in available {
        let ones = survivors.iter().filter(|sig| (**sig >> *action) & 1 == 1).count();
        let p_one = ones as f64 / survivors.len() as f64;
        let score = binary_entropy_bits(p_one) / f64::from(costs[*action as usize]);
        if score > best_score {
            best_score = score;
            best = Some(*action);
        }
    }
    best.or_else(|| available.first().copied())
}
fn choose_uniform_falsification_action(
    singleton: u8,
    candidates: &[Candidate],
    available: &[u8],
    costs: &[u32; DOMAIN],
) -> Option<u8> {
    if candidates.is_empty() {
        return available.first().copied();
    }
    let mut best = None;
    let mut best_score = -1.0f64;
    for action in available {
        let predicted = (singleton >> *action) & 1;
        let disagree = candidates
            .iter()
            .filter(|candidate| ((candidate.sig >> *action) & 1) != predicted)
            .count();
        let score = disagree as f64 / candidates.len() as f64 / f64::from(costs[*action as usize]);
        if score > best_score {
            best_score = score;
            best = Some(*action);
        }
    }
    best.or_else(|| available.first().copied())
}
fn choose_mdl_eig_action(
    survivors: &[u8],
    candidates: &[Candidate],
    available: &[u8],
    costs: &[u32; DOMAIN],
) -> Option<u8> {
    let posterior = posterior_weights(survivors, candidates);
    let mut best = None;
    let mut best_score = -1.0f64;
    for action in available {
        let score = expected_information_gain_per_cost(*action, &posterior, costs);
        if score > best_score {
            best_score = score;
            best = Some(*action);
        }
    }
    best.or_else(|| available.first().copied())
}
fn choose_mdl_falsification_action(
    singleton: u8,
    candidates: &[Candidate],
    available: &[u8],
    costs: &[u32; DOMAIN],
) -> Option<u8> {
    let all: Vec<u8> = candidates.iter().map(|candidate| candidate.sig).collect();
    let prior = posterior_weights(&all, candidates);
    let mut best = None;
    let mut best_score = -1.0f64;
    for action in available {
        let predicted = (singleton >> *action) & 1;
        let disagreement: f64 = prior
            .iter()
            .filter(|(sig, _)| ((sig >> *action) & 1) != predicted)
            .map(|(_, weight)| *weight)
            .sum();
        let score = disagreement / f64::from(costs[*action as usize]);
        if score > best_score {
            best_score = score;
            best = Some(*action);
        }
    }
    best.or_else(|| available.first().copied())
}
fn choose_action(
    survivors: &[u8],
    candidates: &[Candidate],
    available: &[u8],
    costs: &[u32; DOMAIN],
    policy: Policy,
    rng: &mut u64,
) -> Option<u8> {
    match policy {
        Policy::Fixed => available.first().copied(),
        Policy::Random => {
            if available.is_empty() {
                None
            } else {
                Some(available[(next_rng(rng) as usize) % available.len()])
            }
        }
        Policy::Active => {
            let mut best = None;
            let mut best_score = 0usize;
            for action in available {
                let ones = survivors.iter().filter(|sig| (**sig >> *action) & 1 == 1).count();
                let score = ones.min(survivors.len() - ones);
                if score > best_score {
                    best_score = score;
                    best = Some(*action);
                }
            }
            best.or_else(|| available.first().copied())
        }
        Policy::UniformEig => choose_uniform_eig_action(survivors, available, costs),
        Policy::MdlEig => choose_mdl_eig_action(survivors, candidates, available, costs),
    }
}
/// Challenge a unique candidate with one unqueried input. This uses grammar-wide alternatives,
/// not the evaluator target.
fn choose_falsification_action(
    singleton: u8,
    candidates: &[Candidate],
    available: &[u8],
    costs: &[u32; DOMAIN],
    policy: Policy,
    rng: &mut u64,
) -> Option<u8> {
    match policy {
        Policy::Fixed => available.first().copied(),
        Policy::Random => {
            if available.is_empty() {
                None
            } else {
                Some(available[(next_rng(rng) as usize) % available.len()])
            }
        }
        Policy::Active => {
            let mut best = None;
            let mut best_score = 0usize;
            for action in available {
                let predicted = (singleton >> *action) & 1;
                let disagreement = candidates
                    .iter()
                    .filter(|candidate| ((candidate.sig >> *action) & 1) != predicted)
                    .count();
                if disagreement > best_score {
                    best_score = disagreement;
                    best = Some(*action);
                }
            }
            best.or_else(|| available.first().copied())
        }
        Policy::UniformEig => choose_uniform_falsification_action(singleton, candidates, available, costs),
        Policy::MdlEig => choose_mdl_falsification_action(singleton, candidates, available, costs),
    }
}
fn episode_status(remaining: &[u8], obs: &[(u8, u8)]) -> &'static str {
    if remaining.is_empty() {
        "misspecified"
    } else if remaining.len() == 1 && obs.len() == DOMAIN {
        "identified_exactly"
    } else if remaining.len() == 1 {
        "provisional_unique"
    } else {
        "ambiguous"
    }
}
fn run_episode(
    problem: &Problem,
    target_sig: u8,
    candidates: &[Candidate],
    policy: Policy,
    seed: u64,
) -> Episode {
    let target_in_grammar = candidates.iter().any(|c| c.sig == target_sig);
    let mut obs = problem.initial.clone();
    let mut remaining = viable(candidates, &obs);
    let mut available: Vec<u8> = (0..DOMAIN as u8)
        .filter(|a| !obs.iter().any(|(seen, _)| seen == a))
        .collect();
    let mut actions = Vec::new();
    let mut total_cost = 0u32;
    let mut rng = seed;
    while remaining.len() > 1 && actions.len() < problem.budget {
        let Some(a) = choose_action(
            &remaining,
            candidates,
            &available,
            &problem.costs,
            policy,
            &mut rng,
        ) else {
            break;
        };
        // The target simulates the environment response; it is not a chooser input.
        let y = (target_sig >> a) & 1;
        obs.push((a, y));
        actions.push(a);
        total_cost += problem.costs[a as usize];
        available.retain(|v| *v != a);
        remaining.retain(|sig| ((sig >> a) & 1) == y);
    }
    // One post-fit falsification probe challenges a provisional singleton, if budget permits.
    // Passing this probe is not a proof of the full rule unless every domain assignment is observed.
    let mut audit_action = None;
    if remaining.len() == 1
        && actions.len() < problem.budget
        && !available.is_empty()
        && let Some(a) =
            choose_falsification_action(
                remaining[0],
                candidates,
                &available,
                &problem.costs,
                policy,
                &mut rng,
            )
    {
        let y = (target_sig >> a) & 1;
        obs.push((a, y));
        actions.push(a);
        total_cost += problem.costs[a as usize];
        available.retain(|candidate| *candidate != a);
        remaining.retain(|sig| ((sig >> a) & 1) == y);
        audit_action = Some(a);
    }
    let audit_mismatch = audit_action.is_some() && remaining.is_empty();
    let status = episode_status(&remaining, &obs).to_owned();
    let target_retained = target_in_grammar.then(|| remaining.contains(&target_sig));
    Episode {
        split: problem.split.clone(),
        policy: policy.name().to_owned(),
        actions,
        remaining,
        status,
        target_in_grammar,
        target_retained,
        audit_action,
        audit_mismatch,
        total_cost,
    }
}

fn sha256_hex(input: &[u8]) -> String {
    let mut data = input.to_vec();
    let bit_len = (data.len() as u64).wrapping_mul(8);
    data.push(0x80);
    while data.len() % 64 != 56 {
        data.push(0);
    }
    data.extend_from_slice(&bit_len.to_be_bytes());
    let mut h = [
        0x6a09e667u32,
        0xbb67ae85,
        0x3c6ef372,
        0xa54ff53a,
        0x510e527f,
        0x9b05688c,
        0x1f83d9ab,
        0x5be0cd19,
    ];
    for chunk in data.chunks_exact(64) {
        let mut w = [0u32; 64];
        for (i, four) in chunk.chunks_exact(4).take(16).enumerate() {
            w[i] = u32::from_be_bytes([four[0], four[1], four[2], four[3]]);
        }
        for i in 16..64 {
            let s0 = w[i - 15].rotate_right(7) ^ w[i - 15].rotate_right(18) ^ (w[i - 15] >> 3);
            let s1 = w[i - 2].rotate_right(17) ^ w[i - 2].rotate_right(19) ^ (w[i - 2] >> 10);
            w[i] = w[i - 16]
                .wrapping_add(s0)
                .wrapping_add(w[i - 7])
                .wrapping_add(s1);
        }
        let [mut a, mut b, mut c, mut d, mut e, mut f, mut g, mut hh] = h;
        for i in 0..64 {
            let s1 = e.rotate_right(6) ^ e.rotate_right(11) ^ e.rotate_right(25);
            let ch = (e & f) ^ (!e & g);
            let t1 = hh
                .wrapping_add(s1)
                .wrapping_add(ch)
                .wrapping_add(SHA256_K[i])
                .wrapping_add(w[i]);
            let s0 = a.rotate_right(2) ^ a.rotate_right(13) ^ a.rotate_right(22);
            let maj = (a & b) ^ (a & c) ^ (b & c);
            let t2 = s0.wrapping_add(maj);
            hh = g;
            g = f;
            f = e;
            e = d.wrapping_add(t1);
            d = c;
            c = b;
            b = a;
            a = t1.wrapping_add(t2);
        }
        h[0] = h[0].wrapping_add(a);
        h[1] = h[1].wrapping_add(b);
        h[2] = h[2].wrapping_add(c);
        h[3] = h[3].wrapping_add(d);
        h[4] = h[4].wrapping_add(e);
        h[5] = h[5].wrapping_add(f);
        h[6] = h[6].wrapping_add(g);
        h[7] = h[7].wrapping_add(hh);
    }
    let mut out = String::with_capacity(64);
    for word in h {
        use std::fmt::Write as _;
        let _ = write!(out, "{word:08x}");
    }
    out
}
fn git_head() -> Result<String, String> {
    let out = Command::new("git")
        .args(["rev-parse", "HEAD"])
        .output()
        .map_err(|e| format!("could not execute git rev-parse HEAD: {e}"))?;
    if !out.status.success() {
        return Err("git rev-parse HEAD failed; run from a Git checkout".into());
    }
    String::from_utf8(out.stdout)
        .map(|s| s.trim().to_owned())
        .map_err(|e| format!("git returned non-UTF-8 HEAD: {e}"))
}
fn require_clean_worktree() -> Result<(), String> {
    let out = Command::new("git")
        .args(["status", "--porcelain=v1", "--untracked-files=all"])
        .output()
        .map_err(|e| format!("could not execute git status: {e}"))?;
    if !out.status.success() {
        return Err("git status --porcelain failed".into());
    }
    let status = String::from_utf8(out.stdout)
        .map_err(|e| format!("git status returned non-UTF-8 output: {e}"))?;
    if !status.trim().is_empty() {
        return Err(format!(
            "working tree is not clean: {}",
            status.trim().replace('\n', "; ")
        ));
    }
    Ok(())
}
fn json_escape(s: &str) -> String {
    let mut out = String::new();
    for c in s.chars() {
        match c {
            '\\' => out.push_str("\\\\"),
            '"' => out.push_str("\\\""),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            c if c.is_control() => out.push_str(&format!("\\u{:04x}", c as u32)),
            c => out.push(c),
        }
    }
    out
}
fn median(v: &[usize]) -> f64 {
    if v.is_empty() {
        0.0
    } else {
        let m = v.len() / 2;
        if v.len().is_multiple_of(2) {
            v[m - 1] as f64 / 2.0 + v[m] as f64 / 2.0
        } else {
            v[m] as f64
        }
    }
}
fn percentile(v: &[usize], p: f64) -> usize {
    if v.is_empty() {
        0
    } else {
        let rank = ((v.len() as f64 * p).ceil() as usize).max(1);
        v[rank.saturating_sub(1).min(v.len() - 1)]
    }
}
fn median_u32(values: &[u32]) -> f64 {
    if values.is_empty() {
        0.0
    } else {
        let mid = values.len() / 2;
        if values.len().is_multiple_of(2) {
            f64::from(values[mid - 1]) / 2.0 + f64::from(values[mid]) / 2.0
        } else {
            f64::from(values[mid])
        }
    }
}
fn nearest_rank_u32(values: &[u32], p: f64) -> u32 {
    if values.is_empty() {
        0
    } else {
        let rank = ((values.len() as f64 * p).ceil() as usize).max(1);
        values[rank.saturating_sub(1).min(values.len() - 1)]
    }
}
fn summarize(policy: &str, split: &str, eps: &[&Episode]) -> String {
    let n = eps.len();
    let inside: Vec<_> = eps.iter().filter(|e| e.target_in_grammar).collect();
    let retained = inside
        .iter()
        .filter(|e| e.target_retained == Some(true))
        .count();
    let outside: Vec<_> = eps.iter().filter(|e| !e.target_in_grammar).collect();
    let detected = outside
        .iter()
        .filter(|e| e.status == "misspecified")
        .count();
    let provisional_ood = outside
        .iter()
        .filter(|e| e.status == "provisional_unique")
        .count();
    let audit_count = eps.iter().filter(|e| e.audit_action.is_some()).count();
    let audit_mismatch_count = eps.iter().filter(|e| e.audit_mismatch).count();
    let mut q: Vec<usize> = eps.iter().map(|e| e.actions.len()).collect();
    q.sort_unstable();
    let mut costs: Vec<u32> = eps.iter().map(|e| e.total_cost).collect();
    costs.sort_unstable();
    let mean = if n == 0 {
        0.0
    } else {
        q.iter().sum::<usize>() as f64 / n as f64
    };
    format!(
        "{{\"policy\":\"{}\",\"split\":\"{}\",\"episodes\":{},\"mean_queries\":{:.6},\"median_queries\":{:.2},\"p90_queries\":{},\"mean_cost\":{:.6},\"median_cost\":{:.2},\"p90_cost\":{},\"ambiguous\":{},\"provisional_unique\":{},\"identified_exactly\":{},\"misspecified_detected\":{},\"out_of_grammar_episodes\":{},\"out_of_grammar_detection_rate\":{:.6},\"out_of_grammar_provisional_unique\":{},\"in_grammar_episodes\":{},\"in_grammar_target_retention_rate\":{:.6},\"audit_probes\":{},\"audit_detected_misspecifications\":{}}}",
        json_escape(policy),
        json_escape(split),
        n,
        mean,
        median(&q),
        percentile(&q, 0.9),
        if n == 0 { 0.0 } else { costs.iter().map(|v| f64::from(*v)).sum::<f64>() / n as f64 },
        median_u32(&costs),
        nearest_rank_u32(&costs, 0.9),
        eps.iter().filter(|e| e.status == "ambiguous").count(),
        eps.iter()
            .filter(|e| e.status == "provisional_unique")
            .count(),
        eps.iter()
            .filter(|e| e.status == "identified_exactly")
            .count(),
        detected,
        outside.len(),
        if outside.is_empty() {
            0.0
        } else {
            detected as f64 / outside.len() as f64
        },
        provisional_ood,
        inside.len(),
        if inside.is_empty() {
            0.0
        } else {
            retained as f64 / inside.len() as f64
        },
        audit_count,
        audit_mismatch_count
    )
}

fn render_episode(e: &Episode, candidates: &[Candidate]) -> String {
    let rem = e
        .remaining
        .iter()
        .map(|sig| {
            let c = candidates
                .iter()
                .find(|c| c.sig == *sig)
                .expect("remaining signature belongs to grammar");
            format!(
                "{{\"signature\":\"{}\",\"representative\":\"{}\",\"expression_aliases\":{},\"mdl_bits\":{:.8}}}",
                signature_string(c.sig),
                json_escape(&c.representative),
                c.expression_aliases,
                c.mdl_bits
            )
        })
        .collect::<Vec<_>>()
        .join(",");
    let retained = e
        .target_retained
        .map(|x| x.to_string())
        .unwrap_or_else(|| "null".into());
    let audit = e
        .audit_action
        .map(|x| x.to_string())
        .unwrap_or_else(|| "null".into());
    format!(
        "{{\"status\":\"{}\",\"target_in_grammar\":{},\"target_retained_if_in_grammar\":{},\"query_count\":{},\"total_cost\":{},\"actions\":[{}],\"audit_action\":{},\"audit_detected_misspecification\":{},\"remaining_candidates\":[{}]}}",
        e.status,
        e.target_in_grammar,
        retained,
        e.actions.len(),
        e.total_cost,
        e.actions.iter().map(u8::to_string).collect::<Vec<_>>().join(","),
        audit,
        e.audit_mismatch,
        rem
    )
}

fn render_report(
    head: &str,
    max_depth: usize,
    ph: &str,
    th: &str,
    candidates: &[Candidate],
    cases: &[Case],
    episodes: &[Episode],
) -> String {
    let mut summaries = Vec::new();
    for policy in [
        Policy::Active.name(),
        Policy::UniformEig.name(),
        Policy::MdlEig.name(),
        Policy::Fixed.name(),
        Policy::Random.name(),
    ] {
        for split in ["all", "train", "validation", "heldout"] {
            let es: Vec<&Episode> = episodes
                .iter()
                .filter(|e| e.policy == policy && (split == "all" || e.split == split))
                .collect();
            summaries.push(summarize(policy, split, &es));
        }
    }
    let catalog = candidates
        .iter()
        .map(|c| {
            format!(
                "{{\"signature\":\"{}\",\"representative\":\"{}\",\"expression_aliases\":{},\"mdl_bits\":{:.8}}}",
                signature_string(c.sig),
                json_escape(&c.representative),
                c.expression_aliases,
                c.mdl_bits
            )
        })
        .collect::<Vec<_>>()
        .join(",\n    ");
    let rows = cases
        .iter()
        .map(|c| {
            let rs: Vec<&Episode> = c.random.iter().collect();
            format!(
                "{{\"task_id\":\"{}\",\"split\":\"{}\",\"candidate_count\":{},\"initial_viable_candidates\":{},\"active\":{},\"uniform_eig\":{},\"mdl_eig\":{},\"fixed\":{},\"random_repetitions\":{},\"random_summary\":{}}}",
                json_escape(&c.id),
                json_escape(&c.split),
                c.candidate_count,
                c.initial_viable,
                render_episode(&c.active, candidates),
                render_episode(&c.uniform_eig, candidates),
                render_episode(&c.mdl_eig, candidates),
                render_episode(&c.fixed, candidates),
                c.random.len(),
                summarize(Policy::Random.name(), &c.split, &rs)
            )
        })
        .collect::<Vec<_>>()
        .join(",\n    ");
    format!(
        "{{\n  \"schema_version\":1,\n  \"benchmark_id\":\"SIM-REL-003-MDL-EIG-v0\",\n  \"synthetic_only\":true,\n  \"exact_head\":\"{}\",\n  \"max_expression_depth\":{},\n  \"unique_semantic_candidates\":{},\n  \"problem_fixture_sha256\":\"{}\",\n  \"evaluator_truth_fixture_sha256\":\"{}\",\n  \"random_repetitions_per_task\":{},\n  \"prior_definition\":\"PCFG shortest-derivation code length; terminal bits log2(10), operator bits 3 plus child code lengths; one prior per semantic equivalence class\",\n  \"selection_objective\":\"deterministic-observation entropy in bits divided by positive integer action cost\",\n  \"grammar_candidates\":[\n    {}\n  ],\n  \"policy_summaries\":[\n    {}\n  ],\n  \"cases\":[\n    {}\n  ],\n  \"claim_ceiling\":\"bounded three-input Boolean grammar induction with MDL-prior expected information gain per cost; no physical discovery or SOTA superiority claim\"\n}}\n",
        json_escape(head),
        max_depth,
        candidates.len(),
        ph,
        th,
        RANDOM_REPETITIONS,
        catalog,
        summaries.join(",\n    "),
        rows
    )
}
fn run() -> Result<(), Box<dyn std::error::Error>> {
    let (mut pp, mut tp, mut expected, mut output) = (None, None, None, None);
    let mut max_depth = 2usize;
    let mut args = env::args().skip(1);
    while let Some(arg) = args.next() {
        match arg.as_str() {
            "--problems" => pp = args.next(),
            "--truth" => tp = args.next(),
            "--expected-head" => expected = args.next(),
            "--out" => output = args.next(),
            "--max-depth" => {
                max_depth = args.next().ok_or("--max-depth requires value")?.parse()?
            }
            "--help" | "-h" => {
                println!(
                    "sim-rel-bayes --problems PATH --truth PATH --expected-head SHA --out PATH [--max-depth 0..2]"
                );
                return Ok(());
            }
            _ => return Err(format!("unknown argument {arg:?}").into()),
        }
    }
    let pp = pp.ok_or("--problems required")?;
    let tp = tp.ok_or("--truth required")?;
    let expected = expected.ok_or("--expected-head required")?;
    let output = output.ok_or("--out required")?;
    let head = git_head().map_err(|e| format!("identity gate: {e}"))?;
    if head != expected {
        return Err(format!("exact-head mismatch: expected {expected}, got {head}").into());
    }
    require_clean_worktree().map_err(|e| format!("identity gate: {e}"))?;
    let pb = fs::read(pp)?;
    let tb = fs::read(tp)?;
    let ph = sha256_hex(&pb);
    let th = sha256_hex(&tb);
    let tasks = assemble(
        parse_problems(std::str::from_utf8(&pb)?)?,
        parse_truth(std::str::from_utf8(&tb)?)?,
    )?;
    let candidates = enumerate_grammar(max_depth)?;
    let mut cases = Vec::new();
    let mut all = Vec::new();
    for task in &tasks {
        let initial_viable = viable(&candidates, &task.problem.initial).len();
        let active = run_episode(
            &task.problem,
            task.target_sig,
            &candidates,
            Policy::Active,
            stable_seed(&task.problem.id),
        );
        let uniform_eig = run_episode(
            &task.problem,
            task.target_sig,
            &candidates,
            Policy::UniformEig,
            stable_seed(&task.problem.id),
        );
        let mdl_eig = run_episode(
            &task.problem,
            task.target_sig,
            &candidates,
            Policy::MdlEig,
            stable_seed(&task.problem.id),
        );
        let fixed = run_episode(
            &task.problem,
            task.target_sig,
            &candidates,
            Policy::Fixed,
            stable_seed(&task.problem.id),
        );
        let mut random = Vec::new();
        for i in 0..RANDOM_REPETITIONS {
            random.push(run_episode(
                &task.problem,
                task.target_sig,
                &candidates,
                Policy::Random,
                stable_seed(&task.problem.id) ^ ((i as u64) + 1),
            ));
        }
        all.push(active.clone());
        all.push(uniform_eig.clone());
        all.push(mdl_eig.clone());
        all.push(fixed.clone());
        all.extend(random.iter().cloned());
        cases.push(Case {
            id: task.problem.id.clone(),
            split: task.problem.split.clone(),
            candidate_count: candidates.len(),
            initial_viable,
            active,
            uniform_eig,
            mdl_eig,
            fixed,
            random,
        });
    }
    let report = render_report(&head, max_depth, &ph, &th, &candidates, &cases, &all);
    if output == "-" {
        print!("{report}");
    } else {
        fs::write(output, report)?;
    }
    Ok(())
}
fn main() {
    if let Err(e) = run() {
        eprintln!("FAIL: {e}");
        std::process::exit(1);
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    const PROBLEMS: &str = include_str!("../fixtures/problems-v0.tsv");
    const TRUTH: &str = include_str!("../fixtures/evaluator-truth-v0.tsv");
    fn tasks() -> Vec<Task> {
        assemble(
            parse_problems(PROBLEMS).unwrap(),
            parse_truth(TRUTH).unwrap(),
        )
        .unwrap()
    }

    #[test]
    fn sha256_known_vector() {
        assert_eq!(
            sha256_hex(b"abc"),
            "ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad"
        );
    }
    #[test]
    fn grammar_is_bounded_and_semantically_deduplicated() {
        assert_eq!(enumerate_grammar(0).unwrap().len(), 5);
        assert_eq!(enumerate_grammar(1).unwrap().len(), 17);
        assert_eq!(enumerate_grammar(2).unwrap().len(), 109);
        assert!(enumerate_grammar(3).is_err());
    }
    #[test]
    fn majority_is_outside_depth_two_grammar() {
        let s = parse_signature("00010111").unwrap();
        assert!(!enumerate_grammar(2).unwrap().iter().any(|c| c.sig == s));
    }
    #[test]
    fn semantic_aliases_are_grouped() {
        let s = parse_signature("00001111").unwrap();
        let c = enumerate_grammar(2)
            .unwrap()
            .into_iter()
            .find(|c| c.sig == s)
            .unwrap();
        assert!(c.expression_aliases > 1);
        assert_eq!(c.representative, "x");
    }
    #[test]
    fn truth_ids_must_match_problem_ids() {
        let p = parse_problems(PROBLEMS).unwrap();
        let mut t = parse_truth(TRUTH).unwrap();
        t.remove("w_013");
        assert!(assemble(p, t).is_err());
    }
    #[test]
    fn falsification_probe_detects_an_out_of_grammar_target() {
        let target = parse_signature("00010111").unwrap();
        let candidates = enumerate_grammar(2).unwrap();
        let obs: Vec<(u8, u8)> = (0..DOMAIN as u8)
            .filter(|a| *a != 3)
            .map(|a| (a, (target >> a) & 1))
            .collect();
        let p = Problem {
            id: "audit_control".into(),
            split: "heldout".into(),
            initial: obs,
            budget: 1,
            costs: [1; DOMAIN],
        };
        let e = run_episode(&p, target, &candidates, Policy::Active, 1);
        assert_eq!(e.audit_action, Some(3));
        assert!(e.audit_mismatch);
        assert_eq!(e.status, "misspecified");
        assert!(!e.target_in_grammar);
    }
    #[test]
    fn out_of_grammar_full_observation_is_misspecified() {
        let target = parse_signature("00010111").unwrap();
        let c = enumerate_grammar(2).unwrap();
        let obs: Vec<(u8, u8)> = (0..DOMAIN as u8).map(|a| (a, (target >> a) & 1)).collect();
        let p = Problem {
            id: "full_control".into(),
            split: "heldout".into(),
            initial: obs,
            budget: 0,
            costs: [1; DOMAIN],
        };
        let e = run_episode(&p, target, &c, Policy::Active, 1);
        assert_eq!(e.status, "misspecified");
        assert!(!e.target_in_grammar);
    }
    #[test]
    fn selector_does_not_accept_evaluator_target() {
        let c = enumerate_grammar(2).unwrap();
        let live = viable(&c, &[]);
        let mut seed = 1;
        assert!(
            choose_action(
                &live,
                &c,
                &(0..DOMAIN as u8).collect::<Vec<_>>(),
                &[1; DOMAIN],
                Policy::Active,
                &mut seed
            )
            .is_some()
        );
    }
    #[test]
    fn in_grammar_targets_are_never_eliminated() {
        let c = enumerate_grammar(2).unwrap();
        for task in tasks()
            .iter()
            .filter(|t| c.iter().any(|x| x.sig == t.target_sig))
        {
            for policy in [Policy::Active, Policy::UniformEig, Policy::MdlEig, Policy::Fixed, Policy::Random] {
                let e = run_episode(&task.problem, task.target_sig, &c, policy, 17);
                assert_eq!(
                    e.target_retained,
                    Some(true),
                    "{} / {}",
                    task.problem.id,
                    policy.name()
                );
            }
        }
    }
    #[test]
    fn partial_domain_evidence_is_not_called_exact_identification() {
        let c = enumerate_grammar(2).unwrap();
        let target = parse_signature("00001111").unwrap();
        let obs = vec![(0, 0), (1, 0), (2, 0), (3, 0), (4, 1), (5, 1), (6, 1)];
        let p = Problem {
            id: "near_full".into(),
            split: "heldout".into(),
            initial: obs,
            budget: 0,
            costs: [1; DOMAIN],
        };
        let e = run_episode(&p, target, &c, Policy::Active, 1);
        assert_ne!(e.status, "identified_exactly");
    }
    #[test]
    fn uniform_eig_and_mdl_eig_match_when_the_prior_is_uniform() {
        let candidates = vec![
            Candidate { sig: 0, representative: "a".into(), expression_aliases: 1, mdl_bits: 1.0 },
            Candidate { sig: 4, representative: "b".into(), expression_aliases: 1, mdl_bits: 1.0 },
            Candidate { sig: 1, representative: "c".into(), expression_aliases: 1, mdl_bits: 1.0 },
            Candidate { sig: 7, representative: "d".into(), expression_aliases: 1, mdl_bits: 1.0 },
        ];
        let survivors = candidates.iter().map(|c| c.sig).collect::<Vec<_>>();
        let costs = [4, 1, 1, 1, 1, 1, 1, 1];
        assert_eq!(
            choose_uniform_eig_action(&survivors, &[0, 1], &costs),
            choose_mdl_eig_action(&survivors, &candidates, &[0, 1], &costs)
        );
    }
    #[test]
    fn mdl_prior_is_normalized_and_alias_multiplicity_does_not_change_it() {
        let candidates = enumerate_grammar(2).unwrap();
        let signatures: Vec<u8> = candidates.iter().map(|c| c.sig).collect();
        let posterior = posterior_weights(&signatures, &candidates);
        let total: f64 = posterior.iter().map(|(_, p)| *p).sum();
        assert!((total - 1.0).abs() < 1e-12);
        let x = parse_signature("00001111").unwrap();
        let x_candidate = candidates.iter().find(|c| c.sig == x).unwrap();
        assert!(x_candidate.expression_aliases > 1);
        let before = posterior.iter().find(|(sig, _)| *sig == x).unwrap().1;
        let mut altered = candidates.clone();
        altered.iter_mut().find(|c| c.sig == x).unwrap().expression_aliases = 10_000;
        let after = posterior_weights(&signatures, &altered)
            .iter().find(|(sig, _)| *sig == x).unwrap().1;
        assert!((before - after).abs() < 1e-12);
    }
    #[test]
    fn mdl_prior_prefers_shorter_semantic_descriptions() {
        let candidates = enumerate_grammar(2).unwrap();
        let x = parse_signature("00001111").unwrap();
        let xor_xy = parse_signature("00111100").unwrap();
        let x_bits = candidates.iter().find(|c| c.sig == x).unwrap().mdl_bits;
        let xor_bits = candidates.iter().find(|c| c.sig == xor_xy).unwrap().mdl_bits;
        assert!(x_bits < xor_bits);
    }
    #[test]
    fn mdl_eig_prefers_information_per_cost_not_largest_raw_split() {
        let candidates = vec![
            Candidate { sig: 0, representative: "a".into(), expression_aliases: 1, mdl_bits: 1.0 },
            Candidate { sig: 4, representative: "b".into(), expression_aliases: 1, mdl_bits: 1.0 },
            Candidate { sig: 1, representative: "c".into(), expression_aliases: 1, mdl_bits: 1.0 },
            Candidate { sig: 7, representative: "d".into(), expression_aliases: 1, mdl_bits: 1.0 },
        ];
        let survivors = candidates.iter().map(|c| c.sig).collect::<Vec<_>>();
        let action = choose_mdl_eig_action(&survivors, &candidates, &[0, 1], &[4, 1, 1, 1, 1, 1, 1, 1]);
        assert_eq!(action, Some(1));
    }
    #[test]
    fn mdl_eig_validates_costs_and_ties_deterministically() {
        let candidates = enumerate_grammar(1).unwrap();
        let survivors = candidates.iter().map(|c| c.sig).collect::<Vec<_>>();
        let costs = [1; DOMAIN];
        assert_eq!(
            choose_mdl_eig_action(&survivors, &candidates, &[0, 1, 2], &costs),
            choose_mdl_eig_action(&survivors, &candidates, &[0, 1, 2], &costs)
        );
        assert!(parse_costs("1,1,1").is_err());
        assert!(parse_costs("1,1,1,1,1,1,1,0").is_err());
        assert!(parse_costs("1,1,1,1,1,1,1,10001").is_err());
    }
    #[test]
    fn random_policy_is_deterministic() {
        let c = enumerate_grammar(2).unwrap();
        let t = tasks().remove(0);
        let a = run_episode(&t.problem, t.target_sig, &c, Policy::Random, 1234);
        let b = run_episode(&t.problem, t.target_sig, &c, Policy::Random, 1234);
        assert_eq!(a.actions, b.actions);
        assert_eq!(a.remaining, b.remaining);
    }
    #[test]
    fn malformed_inputs_and_invalid_budget_fail_closed() {
        assert!(parse_signature("101").is_err());
        assert!(parse_problems("same|train|none|1|1,1,1,1,1,1,1,1\nsame|heldout|none|1|1,1,1,1,1,1,1,1").is_err());
        assert!(
            parse_problems("one|train|none|9|1,1,1,1,1,1,1,1\ntwo|validation|none|1|1,1,1,1,1,1,1,1\nthree|heldout|none|1|1,1,1,1,1,1,1,1")
                .is_err()
        );
    }
}
